CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT,"email" TEXT UNIQUE,"image" TEXT,"discordId" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerAccountId" TEXT NOT NULL,"refresh_token" TEXT,"access_token" TEXT,"expires_at" INTEGER,"token_type" TEXT,"scope" TEXT,"id_token" TEXT,"session_state" TEXT,UNIQUE("provider","providerAccountId"));
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"sessionToken" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL,"expires" TIMESTAMP(3) NOT NULL);
CREATE TABLE "VerificationToken" ("identifier" TEXT NOT NULL,"token" TEXT NOT NULL UNIQUE,"expires" TIMESTAMP(3) NOT NULL,UNIQUE("identifier","token"));
CREATE TABLE "Character" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"server" TEXT,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","name"));
CREATE TABLE "MarathonWeek" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL UNIQUE,"endsAt" TIMESTAMP(3) NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"location" TEXT,"xp" INTEGER NOT NULL,"allowedDays" JSONB,"maxCompletions" INTEGER NOT NULL DEFAULT 7,"archived" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WeekTask" ("id" TEXT PRIMARY KEY,"weekId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"titleSnapshot" TEXT NOT NULL,"descriptionSnapshot" TEXT NOT NULL,"locationSnapshot" TEXT,"xpSnapshot" INTEGER NOT NULL,"allowedDaysSnapshot" JSONB,"maxCompletionsSnapshot" INTEGER NOT NULL DEFAULT 7,UNIQUE("weekId","taskId"));
CREATE TABLE "CharacterTaskProgress" ("id" TEXT PRIMARY KEY,"characterId" TEXT NOT NULL,"weekTaskId" TEXT NOT NULL,"dayIndex" INTEGER NOT NULL,"completedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("characterId","weekTaskId","dayIndex"));
CREATE TABLE "CharacterTaskNote" ("id" TEXT PRIMARY KEY,"characterId" TEXT NOT NULL,"weekTaskId" TEXT NOT NULL,"text" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("characterId","weekTaskId"));
CREATE TABLE "AdminAuditLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "Account" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "Session" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "Character" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "WeekTask" ADD FOREIGN KEY ("weekId") REFERENCES "MarathonWeek"("id") ON DELETE CASCADE; ALTER TABLE "WeekTask" ADD FOREIGN KEY ("taskId") REFERENCES "Task"("id"); ALTER TABLE "CharacterTaskProgress" ADD FOREIGN KEY ("characterId") REFERENCES "Character"("id") ON DELETE CASCADE; ALTER TABLE "CharacterTaskProgress" ADD FOREIGN KEY ("weekTaskId") REFERENCES "WeekTask"("id") ON DELETE CASCADE; ALTER TABLE "CharacterTaskNote" ADD FOREIGN KEY ("characterId") REFERENCES "Character"("id") ON DELETE CASCADE; ALTER TABLE "CharacterTaskNote" ADD FOREIGN KEY ("weekTaskId") REFERENCES "WeekTask"("id") ON DELETE CASCADE; ALTER TABLE "AdminAuditLog" ADD FOREIGN KEY ("actorId") REFERENCES "User"("id");
